mapper.select:
select a.FINPROD_ID id,a.FINPROD_ABBR text from FIN_PRODUCT a where 1=1
and a.FINPROD_TYPE=#{finprodType}
AND (a.finprod_id like concat('%',concat(#{search},'%')) OR a.finprod_abbr like concat('%',concat(#{search},'%')) OR a.finprod_name like concat('%',concat(#{search},'%')))

SELECT C.Finprod_Id AS finprodId , D.FINPROD_ABBR AS finprodName , A.Inv_Aim AS invAim , E.BOOKSET_DATE AS booksetDate , A.BOK_DETAIL_ID bokDetailId, A.BOOKSET_ID booksetId , D.CCY cyy FROM BOK_STAT_DET_POSIITON A INNER JOIN (select A1.BOOKSET_ID, A1.HAPPEN_DATE, A1.BOK_DETAIL_ID, MAX（A1.BOOK_SUMMARY_ORDER） BOOK_SUMMARY_ORDER from BOK_STAT_DET_POSIITON A1 group by A1.BOOKSET_ID, A1.HAPPEN_DATE, A1.BOK_DETAIL_ID)D ON D.BOOKSET_ID=A.BOOKSET_ID AND D.HAPPEN_DATE=A.HAPPEN_DATE AND D.BOK_DETAIL_ID=A.BOK_DETAIL_ID AND D.BOOK_SUMMARY_ORDER=A.BOOK_SUMMARY_ORDER LEFT JOIN BOK_DETAIL_ID B ON A.BOOKSET_ID = B.BOOKSET_ID AND A.BOK_DETAIL_ID = B.BOK_DETAIL_ID INNER JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.BUSI_ID
AND C.TYPE_1 = #{assetDetailType}
INNER JOIN FIN_PRODUCT D ON C.FINPROD_ID = D.Finprod_Id AND D.FINPROD_TYPE = #{assetType} INNER JOIN BOK_BOOKSET_DATE E ON E.BOOKSET_ID = A.BOOKSET_ID AND A.Happen_Date = E.BOOKSET_DATE -1 AND A.BOOK_DATE < E.BOOKSET_DATE where 1=1 AND A.BOOKSET_ID in
#{setId}
AND C.FINPROD_ID IN
#{finprodId}
AND A.POS_AMT > 0


    	select d.trade_id
			 from TRD_PRODUCT_DEAL d
			 LEFT JOIN BOK_DEAL_ACCOUNTING B ON D.TRADE_ID=B.BUSI_NO
			 where D.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
			  AND D.BUSI_TYPE=#{busiType,jdbcType=VARCHAR} 
			  AND D.FINPROD_TYPE=#{finprodType,jdbcType=VARCHAR} 
			 AND D.TRADE_DATE = #{booksetDate} 
			 AND B.BOOKSET_ID= #{booksetId}
